from admissions_records import *
def s(url,en,ru,pages=None):return S(url,L(en,ru),pages=pages,access='web-pdf-read' if pages else 'web-html-read')

hu='https://www.guide.52school.com/export/sites/default/guidance/net-hosei-ebdp/gid/pdf/2027_GBP_0_Application-Guidelines_20261030.pdf'
record('hosei-university',[route(id='gbp-2027',label=L('Global Business Program, Faculty of Business Administration — September 2027','Global Business Program, Faculty of Business Administration — сентябрь 2027'),programmeIds=['business'],applicability={**cycle(L('September 2027','Сентябрь 2027'),[2027]),'intakes':['fall-2027']},english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic; not Indicator, Online or One Skill Retake','min':6,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4}],'note':L('TOEFL Home Edition and MyBest are not accepted.','TOEFL Home Edition и MyBest не принимаются.')},'waiver':L('Most recent six formal English-medium years in the seven named countries, excluding international schools; or IB Diploma with English A Literature/Language and Literature. Evidence may be requested.','Последние шесть лет формального обучения на английском в семи названных странах, кроме международных школ; либо IB Diploma с English A Literature/Language and Literature. Могут запросить документы.')},academic={'satPolicy':'required-alternatives','note':L('One of SAT, ACT, IB Diploma, or qualifying GCE/International A-levels is required in addition to the university-entrance qualification. A levels require three A subjects, or two A plus two AS subjects.','Обязателен один SAT, ACT, IB Diploma либо подходящие GCE/International A-levels сверх квалификации допуска в университет. A levels требуют три A-предмета либо два A плюс два AS.')},documents=[L('English/Japanese school certificates and complete transcripts; translations by a school official or official agency. Overseas mailed documents must arrive by the deadline; Japan domestic submissions use the postmark rule.','Школьные сертификаты и полные оценки на английском/японском; перевод школьным представителем либо официальным агентством. Зарубежные почтовые документы должны прибыть к сроку; для отправки внутри Японии правило почтового штемпеля.')],sources=[s(hu,'Hosei GBP 2027 guide: eligibility, English and academic alternatives','Hosei GBP: руководство 2027, допуск, английский и академические альтернативы',[1,4,5,6,7,10,11])])],'Added exact GBP 2027 language variants and independent academic alternatives; did not spread the rule to GIS/SCOPE/IGESS.', ['IELTS section minima are unstated; other English degree routes and Japanese-language admission require separate guides.'])

ru='https://en.admission.rikkyo.ac.jp/browse/admissions-requirements/'
record('rikkyo-university',[route(id='peace-2027',label=L('PEACE: CIC / GLAP / International Business Law — 2027','PEACE: CIC / GLAP / International Business Law — 2027'),programmeIds=['business','law','social-sciences','humanities'],applicability=cycle('2027',[2027]),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':94}],'note':L('The new TOEFL alternative requires 4.5 in every section. A single overall 4.5 is not the published condition.','Новая альтернатива TOEFL требует 4,5 в каждой секции. Один общий 4,5 не является опубликованным условием.')},'waiver':L('Specified curriculum English grades can satisfy language proof; IELTS/TOEFL can replace an unmet English prerequisite but do not replace the academic diploma or SAT/ACT total.','Определённые оценки английского своей учебной программы могут подтвердить язык; IELTS/TOEFL могут заменить невыполненный английский предмет, но не академический диплом или общий SAT/ACT.')},academic={'satPolicy':'conditional','note':L('The 2027 page sets different eligibility by curriculum. US/Canadian and five named Asian diplomas use SAT 1170 or ACT 24 with additional English conditions; IB and A-level routes use their own diploma/subject criteria. Higher scholarship thresholds do not guarantee selection.','Страница 2027 задаёт разный допуск по учебным программам. Дипломы США/Канады и пяти названных азиатских систем используют SAT 1170 либо ACT 24 с дополнительным английским; IB и A-levels — собственные критерии диплома/предметов. Более высокие стипендиальные пороги не гарантируют отбор.')},sources=[s(ru,'Rikkyo PEACE 2027 curriculum-specific requirements','Rikkyo PEACE: требования 2027 по школьным системам'),s('https://en.admission.rikkyo.ac.jp/','Rikkyo PEACE English-taught undergraduate programmes','Rikkyo PEACE: англоязычные программы бакалавриата')])],'Separated curriculum prerequisites, language substitution and scholarship thresholds; IELTS alone never establishes PEACE eligibility.', ['The applicant’s exact school category, detailed guide, IELTS sections/test variants and programme campus need individual confirmation.'])

wu='https://www.waseda.jp/fire/sils/en/applicants/faq/'
wa='https://www.waseda.jp/fire/sils/assets/uploads/2025/03/Change-in-Exemption-Requirements-for-Submission-of-English-Proficiency-Test-Score.pdf'
wv='https://www.waseda.jp/fire/sils/assets/uploads/2025/01/New-Requirement-for-the-Validity-Period-of-Standardized-Test-Scores.pdf'
record('waseda-university',[route(id='sils',label=L('School of International Liberal Studies (SILS) English route','Англоязычный маршрут School of International Liberal Studies (SILS)'),programmeIds=['humanities','social-sciences'],english={'requirement':'required-unless-exempt','applicability':cycle(L('Published SILS FAQ; numerical-minimum policy not intake-dated','Опубликованный SILS FAQ; числовая политика минимумов без года набора')),'ielts':{'accepted':True,'variant':'IELTS Academic','noMinimum':True,'role':'admission'},'toefl':{'accepted':True},'waiver':L('From September 2027, exemption requires at least three of the most recent four full-time years in a school/college/university taught solely in English except foreign-language classes. Merely submitting SAT/ACT/English IB no longer establishes exemption.','С сентября 2027 для освобождения нужны минимум три из последних четырёх очных лет в школе/колледже/университете только на английском, кроме иностранных языков. Одной подачи SAT/ACT/английского IB больше недостаточно.'),'note':L('The FAQ explicitly has no minimum English-test score. Its IELTS 6.5 is an exemption from some language classes after admission, not an entry cutoff; compulsory Academic Writing and placement tests remain.','FAQ прямо не устанавливает минимум языкового теста. IELTS 6,5 там освобождает от некоторых языковых занятий после поступления, а не является вступительным порогом; обязательные Academic Writing и распределительные тесты сохраняются.')},academic={'satPolicy':'required-alternatives','applicability':{**cycle(L('From September 2027: standardised test validity notice','С сентября 2027: уведомление о сроке действия академического теста'),[2027]),'intakes':['fall-2027']},'note':L('From September 2027 all applicants submit a standardised test meeting a three-year validity period. SAT/ACT/IB/A-level and other curriculum options require the applicable guide. The FAQ has no minimum test score; admitted-student averages are not cutoffs.','С сентября 2027 все кандидаты подают стандартизированный тест со сроком действия три года. Для SAT/ACT/IB/A-level и других вариантов своей системы нужно применимое руководство. FAQ не задаёт минимум теста; средние зачисленных не являются порогами.')},sources=[s(wu,'SILS FAQ: no cutoff, placement versus admission','SILS FAQ: отсутствие порога, распределение и поступление'),s(wa,'SILS September 2027 English-exemption change','SILS: изменение языкового освобождения с сентября 2027',[1]),s(wv,'SILS September 2027 standardised-test validity','SILS: срок действия академических тестов с сентября 2027',[1])])],'Removed the misleading role of IELTS 6.5 as an admission cutoff and documented the stricter 2027 English-waiver condition.', ['Full September 2027 guide, school-qualification test selection, IELTS variants/sections and exact programme campus still need confirmation.'])

hi='https://juken.hit-u.ac.jp/admission/info/guidelines/files/R9ryuugaku_youkou.pdf'
record('hitotsubashi-university',[route(id='privately-financed-2027',language='ja',label=L('Privately financed international selection — April 2027, Kunitachi','Отбор иностранных студентов за свой счёт — апрель 2027, Kunitachi'),programmeIds=['business','economics','law','social-sciences'],applicability={**cycle(L('April 2027','Апрель 2027'),[2027]),'intakes':['spring-2027']},english={'requirement':'required-unless-exempt','ielts':{'accepted':None},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':48},{'period':'post2026','min':3}],'note':L('Test window: 1 February 2025–31 October 2026; Home Edition accepted, MyBest not accepted. The required English condition is TOEFL; an IELTS substitution is not established.','Окно теста: 1 февраля 2025 — 31 октября 2026; Home Edition принимается, MyBest — нет. Обязательное английское условие — TOEFL; замена IELTS не установлена.')}},academic={'satPolicy':'not-applicable','note':L('The complete numbered eligibility conditions require the applicable school qualification, TOEFL and EJU; SAT/ACT are not listed substitutes in this route. This conclusion is limited to this selection guide.','Полные пронумерованные условия допуска требуют подходящую школьную квалификацию, TOEFL и EJU; SAT/ACT не указаны как замены этого маршрута. Вывод ограничен данным руководством отбора.')},localLanguage=[{'name':'EJU / Japanese examination','requirement':L('EJU Japanese excluding writing + Japan and the World + Mathematics Course 1: combined 680 or more, from the specified 2025 session 1–2026 session 1 window. Separate university Japanese reading/writing examination at Kunitachi. This is not a wholly English-taught degree route.','EJU Japanese без письма + Japan and the World + Mathematics Course 1: общий минимум 680, из указанного окна 1-я сессия 2025 — 1-я сессия 2026. Отдельный университетский экзамен японского чтения/письма в Kunitachi. Это не полностью англоязычный маршрут степени.')}],sources=[s(hi,'Hitotsubashi 2027 privately financed international guide','Hitotsubashi: руководство отбора иностранных студентов за свой счёт 2027',[7,8,9,11,16])])],'Replaced generic English-route ambiguity with the actual Japanese/EJU/TOEFL selection and kept April separate from Fall 2027.', ['Fall 2027 availability or a fully English-taught bachelor route is not established by this April guide; school-equivalence eligibility remains applicant-specific.'])
finish()
